import { supabaseAdmin } from "@/integrations/supabase/client.server";
import { sendWebPush } from "@/lib/web-push.server";

/** Only notifications generated by the database's accepted-participation trigger are eligible. */
export async function dispatchSocialPush(peladaId?: string) {
  if (!process.env["VAPID_PRIVATE_KEY"] || !process.env["VAPID_PUBLIC_KEY"]) return { accepted: 0, configured: false };
  const { data: jobs, error } = await supabaseAdmin.rpc("claim_social_push", peladaId ? { _pelada_id: peladaId } : {});
  if (error) throw new Error("Não foi possível consultar a fila social.");
  let accepted = 0;
  for (const job of jobs ?? []) {
    try {
      if (Date.now() - new Date(job.created_at).getTime() > 86400000) {
        await supabaseAdmin.from("social_push_queue").update({ state: "done" }).eq("notification_id", job.notification_id);
        continue;
      }
      const { data: n, error: notificationError } = await supabaseAdmin.from("notifications").select("user_id,title,body,url,dedupe_key").eq("id", job.notification_id).maybeSingle();
      if (notificationError) throw notificationError;
      if (!n) continue;
      const { data: profile, error: profileError } = await supabaseAdmin.from("profiles").select("notify_follow_activity,suspended_at").eq("id", n.user_id).maybeSingle();
      const { data: follow, error: followError } = await supabaseAdmin.from("user_follows").select("following_id").eq("follower_id", n.user_id).eq("following_id", job.participant_id).maybeSingle();
      const { data: game, error: gameError } = await supabaseAdmin.from("peladas").select("organizer_id").eq("id", job.pelada_id).maybeSingle();
      if (profileError || followError || gameError) throw new Error("Consulta indisponível");
      const { data: blocked, error: blockError } = await supabaseAdmin.rpc("is_blocked", { _a: n.user_id, _b: job.participant_id });
      const { data: organizerBlocked, error: organizerError } = await supabaseAdmin.rpc("is_blocked", { _a: n.user_id, _b: game?.organizer_id ?? job.participant_id });
      const { data: muted, error: muteError } = await supabaseAdmin.from("pelada_mutes").select("user_id").eq("user_id", n.user_id).eq("pelada_id", job.pelada_id).maybeSingle();
      if (blockError || organizerError || muteError) throw new Error("Consulta indisponível");
      let retry = false;
      if (profile?.notify_follow_activity && !profile.suspended_at && follow && game && !blocked && !organizerBlocked && !muted) {
        const { data: subscriptions, error: subscriptionError } = await supabaseAdmin.from("push_subscriptions").select("endpoint,p256dh,auth").eq("user_id", n.user_id);
        if (subscriptionError) throw subscriptionError;
        const acceptedDevices = new Set(job.accepted_devices);
        for (const sub of subscriptions ?? []) {
          const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(sub.endpoint));
          const device = Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, "0")).join("");
          if (acceptedDevices.has(device)) continue;
          const result = await sendWebPush(sub, { title: n.title, ...(n.body ? { body: n.body } : {}), ...(n.url ? { url: n.url } : {}), tag: n.dedupe_key ?? job.notification_id });
          if (result === "ok") {
            accepted++;
            acceptedDevices.add(device);
            const { error: saveError } = await supabaseAdmin.from("social_push_queue").update({ accepted_devices: [...acceptedDevices] }).eq("notification_id", job.notification_id);
            if (saveError) throw saveError;
          }
          if (result === "error") retry = true;
          if (result === "gone") await supabaseAdmin.from("push_subscriptions").delete().eq("endpoint", sub.endpoint).eq("user_id", n.user_id);
        }
      }
      await supabaseAdmin.from("social_push_queue").update({ state: retry ? "pending" : "done" }).eq("notification_id", job.notification_id);
    } catch {
      await supabaseAdmin.from("social_push_queue").update({ state: "pending" }).eq("notification_id", job.notification_id);
      console.error("[social-push] envio pendente; nova tentativa necessária");
    }
  }
  return { accepted, configured: true };
}

export async function attemptSocialPush(peladaId?: string) {
  try { return await dispatchSocialPush(peladaId); }
  catch { console.error("[social-push] fila pendente; nova tentativa necessária"); return { accepted: 0 }; }
}